import{_ as l,o as a,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Month 2021: 5 more ways to break your ceph cluster","description":"","frontmatter":{"title":"Ceph Month 2021: 5 more ways to break your ceph cluster","date":"2021-06-14T00:00:00.000Z","updated":"2021-06-15T00:00:00.000Z","tags":["[Ceph集群管理]","[故障案例分析]","[最佳实践]","[存储技术]","[分布式存储]"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_5_more_ways_to_break_your_ceph_cluster.md","filePath":"posts/2021/Ceph_Month_2021_-_5_more_ways_to_break_your_ceph_cluster.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Month_2021_-_5_more_ways_to_break_your_ceph_cluster.md"};function i(_,e,s,h,n,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>Vito，421的创始人，主持了本次Ceph Month 2021会议，主题为“破坏你的Ceph集群的五种新方法及一个额外提示”。本次会议回顾了Vito之前关于“破坏Ceph集群的十种方法”的演讲，并分享了新的研究和经验教训。</p><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>自动化工具的误用</strong>：</p><ul><li>案例分析：自动化脚本未正确检查监控器数量，导致监控器被错误移除，包括监控数据库，造成严重停机。</li><li>教训：自动化工具的使用需谨慎，确保所有必要的检查和配置都已正确设置。</li></ul></li><li><p><strong>监控器的重要性误解</strong>：</p><ul><li>案例分析：用户错误地认为监控器可以随意移除和重新创建，导致系统监控功能受损。</li><li>教训：监控器在Ceph集群中扮演关键角色，不应随意操作。</li></ul></li><li><p><strong>配置错误</strong>：</p><ul><li>案例分析：集群配置中的最小副本数设置不当，导致数据恢复困难或数据丢失。</li><li>教训：建议始终使用至少三个副本以确保数据安全。</li></ul></li><li><p><strong>升级不完全</strong>：</p><ul><li>案例分析：未完全遵循升级指南进行升级，导致集群在一段时间后出现问题。</li><li>教训：升级过程中应严格遵循官方指南，确保所有步骤都已完成。</li></ul></li><li><p><strong>过早完成升级</strong>：</p><ul><li>案例分析：在未完全升级所有守护进程的情况下，启用增强安全设置，导致服务连接问题。</li><li>教训：升级应确保所有相关组件都已更新到最新状态。</li></ul></li><li><p><strong>PG自动缩放器的盲目信任</strong>：</p><ul><li>案例分析：集群在数据量增加后，PG自动缩放器错误地增加了放置组，导致数据错位。</li><li>教训：应谨慎使用PG自动缩放器，并监控其行为以避免数据管理问题。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>强调了自动化工具、监控器管理、配置设置、升级过程和PG自动缩放器使用的重要性。</li><li>提醒用户应持续关注和学习Ceph的最佳实践和更新，以避免潜在的风险。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>用户应重新评估和优化其Ceph集群的管理和配置，确保遵循最佳实践。</li><li>定期进行培训和知识更新，以提高对Ceph集群管理的理解和技能。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在讨论和解答与会者的疑问后结束，强调了持续学习和实践的重要性，以确保Ceph集群的稳定和高效运行。</p>',11)])])}const d=l(r,[["render",i]]);export{c as __pageData,d as default};
